import{_ as t,o as e,c as o,a8 as r}from"./chunks/framework.DQoZbSQ3.js";const b=JSON.parse('{"title":"Chatbox 接入指南","description":"","frontmatter":{"title":"Chatbox 接入指南","date":"2026-05-18T00:00:00.000Z","category":"拓展","tags":["Chatbox","AI客户端","接入教程","全平台"]},"headers":[],"relativePath":"connect/chatbox.md","filePath":"connect/chatbox.md","lastUpdated":1779073000000}'),h={name:"connect/chatbox.md"};function n(d,a,i,c,p,l){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="chatbox-接入指南" tabindex="-1">Chatbox 接入指南 <a class="header-anchor" href="#chatbox-接入指南" aria-label="Permalink to &quot;Chatbox 接入指南&quot;">​</a></h1><p>全平台支持的轻量 AI 客户端，配合熊猫Token平台快速上手。</p><p><strong>预计用时：3 分钟 · 支持平台：Win / Mac / iOS / Android / 网页版</strong></p><hr><h2 id="什么是-chatbox" tabindex="-1">什么是 Chatbox？ <a class="header-anchor" href="#什么是-chatbox" aria-label="Permalink to &quot;什么是 Chatbox？&quot;">​</a></h2><p>Chatbox 是一款开源 AI 客户端，支持所有主流平台，聊天记录完全保存在本地，隐私有保障。操作简单，适合普通用户和开发者。接入熊猫Token平台后，可以低成本使用 GPT-4、Claude、DeepSeek 等所有模型。</p><p>支持平台：Windows · macOS · Linux · iOS · Android · 网页版</p><hr><h2 id="step-01-下载安装-chatbox" tabindex="-1">Step 01：下载安装 Chatbox <a class="header-anchor" href="#step-01-下载安装-chatbox" aria-label="Permalink to &quot;Step 01：下载安装 Chatbox&quot;">​</a></h2><h3 id="_1-访问官网下载" tabindex="-1">1. 访问官网下载 <a class="header-anchor" href="#_1-访问官网下载" aria-label="Permalink to &quot;1. 访问官网下载&quot;">​</a></h3><p>前往 <a href="https://chatboxai.app/zh" target="_blank" rel="noreferrer">chatboxai.app/zh</a>，选择你的设备平台点击下载。也可以直接使用网页版，免安装。</p><h3 id="_2-安装并打开" tabindex="-1">2. 安装并打开 <a class="header-anchor" href="#_2-安装并打开" aria-label="Permalink to &quot;2. 安装并打开&quot;">​</a></h3><p>桌面端下载完成后双击安装包，按提示完成安装，启动 Chatbox。</p><hr><h2 id="step-02-获取熊猫token-api-key" tabindex="-1">Step 02：获取熊猫Token API Key <a class="header-anchor" href="#step-02-获取熊猫token-api-key" aria-label="Permalink to &quot;Step 02：获取熊猫Token API Key&quot;">​</a></h2><h3 id="_1-登录平台" tabindex="-1">1. 登录平台 <a class="header-anchor" href="#_1-登录平台" aria-label="Permalink to &quot;1. 登录平台&quot;">​</a></h3><p>访问 <a href="https://www.pandatoken.net" target="_blank" rel="noreferrer">www.pandatoken.net</a>，注册并登录账号。</p><h3 id="_2-创建-api-key" tabindex="-1">2. 创建 API Key <a class="header-anchor" href="#_2-创建-api-key" aria-label="Permalink to &quot;2. 创建 API Key&quot;">​</a></h3><p>进入「控制台」→「令牌」，点击新建令牌，复制生成的 Key（只显示一次，请妥善保存）。</p><hr><h2 id="step-03-在-chatbox-中配置" tabindex="-1">Step 03：在 Chatbox 中配置 <a class="header-anchor" href="#step-03-在-chatbox-中配置" aria-label="Permalink to &quot;Step 03：在 Chatbox 中配置&quot;">​</a></h2><h3 id="_1-打开设置" tabindex="-1">1. 打开设置 <a class="header-anchor" href="#_1-打开设置" aria-label="Permalink to &quot;1. 打开设置&quot;">​</a></h3><p>启动 Chatbox 后，如果弹出配置引导直接按提示操作；如果没有，点击左下角「设置」图标 → 「模型提供方」。</p><h3 id="_2-添加自定义提供方" tabindex="-1">2. 添加自定义提供方 <a class="header-anchor" href="#_2-添加自定义提供方" aria-label="Permalink to &quot;2. 添加自定义提供方&quot;">​</a></h3><p>点击「添加」或「添加自定义提供方」，在弹出的表单中填写：</p><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>名称</td><td>熊猫Token</td></tr><tr><td>API 域名</td><td><code>https://www.pandatoken.net/v1</code></td></tr><tr><td>API 路径</td><td><code>/chat/completions</code>（默认，无需修改）</td></tr><tr><td>API 密钥</td><td>你复制的 Key</td></tr></tbody></table><h3 id="_3-添加模型" tabindex="-1">3. 添加模型 <a class="header-anchor" href="#_3-添加模型" aria-label="Permalink to &quot;3. 添加模型&quot;">​</a></h3><p>在模型输入框中，手动输入你想使用的模型名称，例如：</p><p><code>deepseek-v3</code> · <code>gpt-4o</code> · <code>claude-3-5-sonnet-20241022</code> · <code>gemini-2.0-flash</code></p><div class="tip custom-block"><p class="custom-block-title">查看所有可用模型</p><p>可到熊猫Token平台「模型广场」查看所有可用模型名称及 ID。</p></div><h3 id="_4-保存并开始使用" tabindex="-1">4. 保存并开始使用 <a class="header-anchor" href="#_4-保存并开始使用" aria-label="Permalink to &quot;4. 保存并开始使用&quot;">​</a></h3><p>保存配置后，在聊天界面上方的模型选择栏切换到熊猫Token的模型，即可开始对话。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>提示 401 / API Key 错误</strong></p><p>请确认复制的 Key 完整，没有多余空格。Key 只在创建时显示一次，如果忘了请重新生成。</p><p><strong>模型列表中选不到想要的模型</strong></p><p>Chatbox 需要手动输入模型名称，不会自动拉取列表。请参考熊猫Token平台「模型广场」的模型 ID 手动输入。</p><hr><p>配置完成！Chatbox 已成功接入熊猫Token平台，即可低成本畅用所有模型。</p>',40)])])}const x=t(h,[["render",n]]);export{b as __pageData,x as default};
